from http.server import BaseHTTPRequestHandler, HTTPServer
import sys
class H(BaseHTTPRequestHandler):
    def do_GET(self): self.handle_req()
    def do_HEAD(self): self.handle_req(head_only=True)
    def do_POST(self): self.handle_req()
    def handle_req(self, head_only=False):
        sys.stderr.write(f"REQ {self.command} {self.path}\n"); sys.stderr.flush()
        p = self.path.split('?')[0]
        def send(code, body, extra={}):
            if isinstance(body, str): body=body.encode()
            self.send_response(code)
            self.send_header("Content-Length", str(len(body)))
            for k,v in extra.items(): self.send_header(k,v)
            self.end_headers()
            if not head_only and self.command != "HEAD": self.wfile.write(body)
        if p == "/" or p == "":
            send(200, b"hi")
        elif p == "/file":
            send(200, b"filecontent")
        elif p == "/dir":
            send(301, b"", {"Location": "/dir/"})
        elif p == "/dir/":
            send(200, b"dir index")
        elif p == "/listable":
            send(301, b"", {"Location": "/listable/"})
        elif p == "/listable/":
            send(200, b"<html><title>Index of /listable/</title><body><a href='a'>a</a></body></html>")
        elif p == "/forbidden":
            send(403, b"forbidden!!")
        elif p == "/unauth":
            send(401, b"unauthorized!")
        elif p == "/servererror":
            send(500, b"error")
        elif p == "/redirect":
            send(302, b"", {"Location": "/file"})
        elif p == "/notfound":
            send(404, b"not found")
        elif p == "/dir/fileinside":
            send(200, b"inside")
        elif p == "/emptydir":
            send(301, b"", {"Location": "/emptydir/"})
        elif p == "/emptydir/":
            send(200, b"<html>empty</html>")
        else:
            # validation random strings -> 404
            send(404, b"not found")
    def log_message(self, *a): pass
