from http.server import BaseHTTPRequestHandler, HTTPServer
import sys, base64
class H(BaseHTTPRequestHandler):
    def do_GET(self): self.myhandle()
    def do_HEAD(self): self.myhandle(head=True)
    def do_POST(self): self.myhandle()
