        p=self.path.split('?')[0]
        sys.stderr.write(f"REQ {self.command} {p} UA={self.headers.get('User-Agent')} Cookie={self.headers.get('Cookie')} X={self.headers.get('X-Custom')} X2={self.headers.get('X-Second')} Auth={self.headers.get('Authorization')}\n"); sys.stderr.flush()
        def send(code, body, extra={}):
            if isinstance(body,str): body=body.encode()
            self.send_response(code)
            self.send_header("Content-Length",str(len(body)))
            for k,v in extra.items(): self.send_header(k,v)
            self.end_headers()
            if not head and self.command!="HEAD": self.wfile.write(body)
        if p=="/": send(200,b"hi")
