# === Color helpers ===
def color_code(code, use_color):
    if not use_color:
        return str(code)
    if 200 <= code <= 299:
        return f"\x1b[32m{code}\x1b[0m"
    elif 300 <= code <= 399:
        return f"\x1b[36m{code}\x1b[0m"
    elif 400 <= code <= 499:
        return f"\x1b[31m{code}\x1b[0m"
    elif 500 <= code <= 599:
        return f"\x1b[33m{code}\x1b[0m"
    else:
        return str(code)

def format_found(url, code, size, is_dir, is_listable, redirect_url, use_color, for_report=False):
    # for_report: if True, prefix with "  " (two spaces) for TTY footer? Actually TTY footer has "  " prefix, piped report (txt file) has no prefix.
    # This function for console live (no prefix) and for TTY footer (with prefix)? We'll handle prefix outside.
    # For L (listable), prefix is bold: "\x1b[1mL \x1b[0m" when use_color, else "L "
    # For D, prefix "D ", for +, "+ "
    if is_listable:
        if use_color:
            prefix = "\x1b[1mL \x1b[0m"
        else:
            prefix = "L "
    elif is_dir:
        prefix = "D "
    else:
        prefix = "+ "
    code_str = color_code(code, use_color)
    if redirect_url and code in (301, 302):
        # Only 301/302 show DEST? What about 301/302 for dirs? Dirs don't show DEST (they show final URL with final code). Good. This is for files with redirect.
        line = f"{prefix}{url} (CODE:{code_str}|SIZE:{size}|DEST:{redirect_url})"
    else:
        line = f"{prefix}{url} (CODE:{code_str}|SIZE:{size})"
    return line

