        if config.hide_ranges and is_hidden_size(size, config.hide_ranges):
            if config.verbose >= 2:
                log_trace(tid, "dirble::request_thread", "src/request_thread.rs:186", f"[{full_url}]: length {size} is in a blacklist range")
            return ('filtered', full_url)
        if "/.ht" in full_url and code == 403 and not config.show_htaccess:
            return ('filtered', full_url)
        return ('file', full_url, code, size)
